local ParkourRewardDialogCell = Class("ParkourRewardDialogCell")
function ParkourRewardDialogCell:__init()
	self._data = nil
	self._cb = nil
end

function ParkourRewardDialogCell:__delete()
	self._data = nil
	self._cb = nil
end

function ParkourRewardDialogCell:Awake()

end

function ParkourRewardDialogCell:Refresh(data, cb, index, pointId)
	if not data then
		return
	end
	self._data = data
	self.index = index
	self._cb = cb
	if checkNumber(pointId) > 0 then
		local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(pointId)
		if isNotNull(goodsVo) then
			CfUtils.FillImage(self.ImgIconActivity, goodsVo.photoPath)
		end
	end

	self:FillSelf()
end

function ParkourRewardDialogCell:FillSelf()
	
	local isCanDraw = self._data.status == 1
	local isDraw = self._data.status == 2
	
	CfUtils.SetUISwitchImage(self.ImgBar, isDraw and 2 or 1)
	CfUtils.SetUISwitchImage(self.ImgBar2, isDraw and 2 or 1)
	CfUtils.SetUISwitchImage(self.Fill, isDraw and 2 or 1)
	
	local curNum = checkNumber(self._data.progress)
	CfUtils.FillText(self.Text, localize("<color=#545454><size=30>_num1_</size></color>/_num2_", {_num1_ = curNum, _num2_ = self._data.targetNum}))
	self.SliderComplete.value = curNum/checkNumber(self._data.targetNum)
	
	CfUtils.SetActive(self.FontStyleButton, not isDraw and isCanDraw)
	CfUtils.SetActive(self.Complete, isDraw)
	CfUtils.SetActive(self.Underway, not isCanDraw and not isDraw)
	
	local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
	rewardEnv:FreshBaseUI(self._data.rewards, nil, isDraw)
	
	
	if isCanDraw then
		--已领取
		if isDraw then
		
		else
			SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrawReward))
		end
	else
	end
end

--领取奖励
function ParkourRewardDialogCell:OnDrawReward()
	if not self._data then
		return
	end
	
	local isCanDraw = self._data.status == 1
	local isDraw = self._data.status == 2
	
	if not isCanDraw then
		GameUtils.Toast(localize("未达成领取条件"))
		return
	elseif isDraw then
		GameUtils.Toast(localize("该奖励已领取"))
		return
	end
	
	if self._cb then
		self._cb(self.index)
	end
end

function ParkourRewardDialogCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
	self = nil
end

return ParkourRewardDialogCell